<div class="grid-2"><div class="card"><h3>Registrar usuario</h3><form method="post" action="<?= e(url('usuario','store')) ?>" class="form-grid one"><?= csrf_field() ?><label>Nombre<input name="nombre" required maxlength="120"></label><label>Correo<input type="email" name="correo" required maxlength="150"></label><label>Contraseña temporal<input type="password" name="clave" required minlength="8"></label><label>Rol<select name="rol_id"><?php foreach($roles as $r): ?><option value="<?= (int)$r['id'] ?>"><?= e($r['nombre']) ?></option><?php endforeach; ?></select></label><label>Estado<select name="estado"><option>ACTIVO</option><option>INACTIVO</option></select></label><button class="btn btn-primary">Guardar usuario</button></form></div><div class="card"><h3>Usuarios</h3><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Estado</th></tr></thead><tbody><?php foreach($usuarios as $u): ?><tr><td><?= e($u['nombre']) ?></td><td><?= e($u['correo']) ?></td><td><?= e($u['rol']) ?></td><td><?= e($u['estado']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
